<script setup lang="ts">defineProps<{modelValue:string;label:string;type?:string;placeholder?:string;autocomplete?:string;error?:string}>();defineEmits<{(e:'update:modelValue',value:string):void}>()</script><template><label class="field"><span>{{label}}</span><input :value="modelValue" :type="type||'text'" :placeholder="placeholder" :autocomplete="autocomplete" :aria-invalid="Boolean(error)" @input="$emit('update:modelValue',($event.target as HTMLInputElement).value)"><small v-if="error">{{error}}</small></label></template><style scoped>.field{display:grid;gap:7px;font-size:14px;font-weight:600;color:var(--ds-text)}input{min-height:44px;padding:0 12px;border:1px solid var(--ds-border-strong);border-radius:var(--ds-radius-md);background:var(--ds-surface);color:var(--ds-text);transition:border-color 120ms,box-shadow 120ms}input:focus{border-color:var(--ds-focus)}input[aria-invalid=true]{border-color:var(--ds-danger)}small{color:var(--ds-danger);font-weight:500}</style>